int divide(int a, int b) {
    if (b == 0) {
        return -1; // Error code for division by zero
    }
    return a / b;
}

int main() {
    printf("%d\n", divide(10, 0));
    return 0;
}
```

When using this method, the calling function would need to check the return value and act accordingly.

A more structured approach using error codes can look like this:

```c
#include <stdio.h>

#define DIVISION_BY_ZERO -1
#define INVALID_INPUT -2

int divide(int a, int b) {
    if (b == 0) {
        return DIVISION_BY_ZERO;
    } else if (a < 0 || b < 0) {
        return INVALID_INPUT;
    }
    return a / b;
}

int main() {
    int result = divide(10, 0);
    if (result == DIVISION_BY_ZERO) {
        printf("Error: Division by zero\n");
    } else if (result == INVALID_INPUT) {
        printf("Error: Invalid input\n");
    } else {
        printf("%d\n", result);
    }
    return 0;
}
```

For a more object-oriented approach, you might define a struct to represent the error:

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int code;
    char *message;
} error_t;

error_t create_error(int code, char *message) {
    error_t error;
    error.code = code;
    error.message = malloc(strlen(message) + 1);
    strcpy(error.message, message);
    return error;
}

void free_error(error_t *error) {
    free(error->message);
}

int divide(int a, int b) {
    if (b == 0) {
        return create_error(-1, "Division by zero");
    } else if (a < 0 || b < 0) {
        return create_error(-2, "Invalid input");
    }
    return a / b;
}

int main() {
    error_t result = divide(10, 0);
    if (result.code == -1) {
        printf("Error: %s\n", result.message);
        free_error(&result);
    } else if (result.code == -2) {
        printf("Error: %s\n", result.message);
        free_error(&result);
    } else {
        printf("%d\n", result);
        free_error(&result);
    }
    return 0;
}
```

Each of these methods has its advantages and can be used depending on the specific requirements of the project and the level of complexity desired.

